        'code' => $code, 'badge_state' => $paid ? 'paid' : 'pending', 'badge_color' => $paid ? '#087f46' : '#995500', 'badge_bg' => $paid ? '#d7f2df' : '#fff1cf', 'payment_badge' => $paid ? 'Pago' : 'Pagamento pendente',
        'listing_title' => $d['titulo'] . (!empty($d['localizacao']) ? ' · ' . $d['localizacao'] : ''),
