        'end' => $tipo === 'experiencia' ? ($d['horario'] ?? '') : emailReservaData($d['fim'] ?? '') . (!empty($d['hora_fim']) ? ' · ' . $d['hora_fim'] : ''),
        'duration_people' => $d['detalhes'] ?? '',
