        'host_contact' => $host !== '' ? '<b>' . $e(['alojamento' => 'Alojamento', 'carro' => 'Rent-a-car', 'experiencia' => 'Organizador'][$tipo]) . ':</b><br>' . $host : 'Consulte os contactos do anfitrião na sua reserva.',
