    static function getRSBlocks($typeNumber, $errorCorrectLevel) {

        $rsBlock = QRRSBlock::getRsBlockTable($typeNumber, $errorCorrectLevel);
        $length = count($rsBlock) / 3;

        $list = array();

        for ($i = 0; $i < $length; $i++) {

            $count = $rsBlock[$i * 3 + 0];
            $totalCount = $rsBlock[$i * 3 + 1];
            $dataCount  = $rsBlock[$i * 3 + 2];

            for ($j = 0; $j < $count; $j++) {
                $list[] = new QRRSBlock($totalCount, $dataCount);
            }
        }

        return $list;
    }

    static function getRsBlockTable($typeNumber, $errorCorrectLevel) {

        switch($errorCorrectLevel) {
        case QR_ERROR_CORRECT_LEVEL_L :
            return self::$QR_RS_BLOCK_TABLE[($typeNumber - 1) * 4 + 0];
        case QR_ERROR_CORRECT_LEVEL_M :
            return self::$QR_RS_BLOCK_TABLE[($typeNumber - 1) * 4 + 1];
        case QR_ERROR_CORRECT_LEVEL_Q :
            return self::$QR_RS_BLOCK_TABLE[($typeNumber - 1) * 4 + 2];
        case QR_ERROR_CORRECT_LEVEL_H :
            return self::$QR_RS_BLOCK_TABLE[($typeNumber - 1) * 4 + 3];
        default :
            trigger_error("tn:$typeNumber/ecl:$errorCorrectLevel", E_USER_ERROR);
        }
    }
}

//---------------------------------------------------------------
// QRNumber
//---------------------------------------------------------------

class QRNumber extends QRData {

    function __construct($data) {
        parent::__construct(QR_MODE_NUMBER, $data);
    }

    function write(&$buffer) {

        $data = $this->getData();

        $i = 0;

        while ($i + 2 < strlen($data) ) {
            $num = QRNumber::parseInt(substr($data, $i, 3) );
            $buffer->put($num, 10);
            $i += 3;
        }

        if ($i < strlen($data) ) {

            if (strlen($data) - $i == 1) {
                $num = QRNumber::parseInt(substr($data, $i, $i + 1) );
                $buffer->put($num, 4);
            } else if (strlen($data) - $i == 2) {
                $num = QRNumber::parseInt(substr($data, $i, $i + 2) );
                $buffer->put($num, 7);
            }
        }
    }

    static function parseInt($s) {

        $num = 0;
        for ($i = 0; $i < strlen($s); $i++) {
            $num = $num * 10 + QRNumber::parseIntAt(ord($s[$i]) );
        }
        return $num;
    }

    static function parseIntAt($c) {

        if (QRUtil::toCharCode('0') <= $c && $c <= QRUtil::toCharCode('9') ) {
            return $c - QRUtil::toCharCode('0');
        }

        trigger_error("illegal char : $c", E_USER_ERROR);
    }
}

//---------------------------------------------------------------
// QRKanji
//---------------------------------------------------------------

class QRKanji extends QRData {

    function __construct($data) {
        parent::__construct(QR_MODE_KANJI, $data);
    }

    function write(&$buffer) {

        $data = $this->getData();

        $i = 0;

        while ($i + 1 < strlen($data) ) {

            $c = ( (0xff & ord($data[$i]) ) << 8) | (0xff & ord($data[$i + 1]) );

            if (0x8140 <= $c && $c <= 0x9FFC) {
                $c -= 0x8140;
            } else if (0xE040 <= $c && $c <= 0xEBBF) {
                $c -= 0xC140;
            } else {
                trigger_error("illegal char at " . ($i + 1) . "/$c", E_USER_ERROR);
            }

            $c = ( ($c >> 8) & 0xff) * 0xC0 + ($c & 0xff);

            $buffer->put($c, 13);

            $i += 2;
        }

        if ($i < strlen($data) ) {
            trigger_error("illegal char at " . ($i + 1), E_USER_ERROR);
        }
    }

    function getLength() {
        return floor(strlen($this->getData() ) / 2);
    }
}

//---------------------------------------------------------------
// QRAlphaNum
//---------------------------------------------------------------

class QRAlphaNum extends QRData {

    function __construct($data) {
        parent::__construct(QR_MODE_ALPHA_NUM, $data);
    }

    function write(&$buffer) {

        $i = 0;
        $c = $this->getData();

        while ($i + 1 < strlen($c) ) {
            $buffer->put(QRAlphaNum::getCode(ord($c[$i]) ) * 45
                + QRAlphaNum::getCode(ord($c[$i + 1]) ), 11);
            $i += 2;
        }

        if ($i < strlen($c) ) {
            $buffer->put(QRAlphaNum::getCode(ord($c[$i])), 6);
        }
    }

    static function getCode($c) {

        if (QRUtil::toCharCode('0') <= $c
                && $c <= QRUtil::toCharCode('9') ) {
            return $c - QRUtil::toCharCode('0');
        } else if (QRUtil::toCharCode('A') <= $c
                && $c <= QRUtil::toCharCode('Z') ) {
            return $c - QRUtil::toCharCode('A') + 10;
        } else {
            switch ($c) {
            case QRUtil::toCharCode(' ') : return 36;
            case QRUtil::toCharCode('$') : return 37;
            case QRUtil::toCharCode('%') : return 38;
            case QRUtil::toCharCode('*') : return 39;
            case QRUtil::toCharCode('+') : return 40;
            case QRUtil::toCharCode('-') : return 41;
            case QRUtil::toCharCode('.') : return 42;
            case QRUtil::toCharCode('/') : return 43;
            case QRUtil::toCharCode(':') : return 44;
            default :
                trigger_error("illegal char : $c", E_USER_ERROR);
            }
        }

    }
}

//---------------------------------------------------------------
// QR8BitByte
//---------------------------------------------------------------

class QR8BitByte extends QRData {

    function __construct($data) {
        parent::__construct(QR_MODE_8BIT_BYTE, $data);
    }

    function write(&$buffer) {

        $data = $this->getData();
        for ($i = 0; $i < strlen($data); $i++) {
            $buffer->put(ord($data[$i]), 8);
        }
    }

}

//---------------------------------------------------------------
// QRData
//---------------------------------------------------------------

abstract class QRData {

    var $mode;

    var $data;

    function __construct($mode, $data) {
        $this->mode = $mode;
        $this->data = $data;
    }

    function getMode() {
        return $this->mode;
    }

    function getData() {
        return $this->data;
    }

    /**
     * @return int
     */
    function getLength() {
        return strlen($this->getData() );
    }

    /**
     * @param \QRBitBuffer $buffer
     */
    abstract function write(&$buffer);

    function getLengthInBits($type) {

        if (1 <= $type && $type < 10) {

            // 1 - 9

            switch($this->mode) {
            case QR_MODE_NUMBER     : return 10;
            case QR_MODE_ALPHA_NUM     : return 9;
            case QR_MODE_8BIT_BYTE    : return 8;
            case QR_MODE_KANJI      : return 8;
            default :
                trigger_error("mode:$this->mode", E_USER_ERROR);
            }

        } else if ($type < 27) {

            // 10 - 26

            switch($this->mode) {
            case QR_MODE_NUMBER     : return 12;
            case QR_MODE_ALPHA_NUM     : return 11;
            case QR_MODE_8BIT_BYTE    : return 16;
            case QR_MODE_KANJI      : return 10;
            default :
                trigger_error("mode:$this->mode", E_USER_ERROR);
            }

        } else if ($type < 41) {

            // 27 - 40

            switch($this->mode) {
            case QR_MODE_NUMBER     : return 14;
            case QR_MODE_ALPHA_NUM    : return 13;
            case QR_MODE_8BIT_BYTE    : return 16;
            case QR_MODE_KANJI      : return 12;
            default :
                trigger_error("mode:$this->mode", E_USER_ERROR);
            }

        } else {
            trigger_error("mode:$this->mode", E_USER_ERROR);
        }
    }

}

//---------------------------------------------------------------
// QRMath
//---------------------------------------------------------------

class QRMath {

    static $QR_MATH_EXP_TABLE = null;
    static $QR_MATH_LOG_TABLE = null;

    static function init() {

        self::$QR_MATH_EXP_TABLE = QRMath::createNumArray(256);

        for ($i = 0; $i < 8; $i++) {
            self::$QR_MATH_EXP_TABLE[$i] = 1 << $i;
        }

        for ($i = 8; $i < 256; $i++) {
            self::$QR_MATH_EXP_TABLE[$i] = self::$QR_MATH_EXP_TABLE[$i - 4]
                ^ self::$QR_MATH_EXP_TABLE[$i - 5]
                ^ self::$QR_MATH_EXP_TABLE[$i - 6]
                ^ self::$QR_MATH_EXP_TABLE[$i - 8];
        }

        self::$QR_MATH_LOG_TABLE = QRMath::createNumArray(256);

        for ($i = 0; $i < 255; $i++) {
            self::$QR_MATH_LOG_TABLE[self::$QR_MATH_EXP_TABLE[$i] ] = $i;
        }
    }

    static function createNumArray($length) {
        $num_array = array();
        for ($i = 0; $i < $length; $i++) {
            $num_array[] = 0;
        }
        return $num_array;
    }

    static function glog($n) {

        if ($n < 1) {
            trigger_error("log($n)", E_USER_ERROR);
        }

        return self::$QR_MATH_LOG_TABLE[$n];
    }

    static function gexp($n) {

        while ($n < 0) {
            $n += 255;
        }

        while ($n >= 256) {
            $n -= 255;
        }

        return self::$QR_MATH_EXP_TABLE[$n];
    }
}

// init static table
QRMath::init();

//---------------------------------------------------------------
// QRPolynomial
//---------------------------------------------------------------

class QRPolynomial {

    var $num;

    function __construct($num, $shift = 0) {

        $offset = 0;

        while ($offset < count($num) && $num[$offset] == 0) {
            $offset++;
        }

        $this->num = QRMath::createNumArray(count($num) - $offset + $shift);
        for ($i = 0; $i < count($num) - $offset; $i++) {
            $this->num[$i] = $num[$i + $offset];
        }
    }

    function get($index) {
        return $this->num[$index];
    }

    function getLength() {
        return count($this->num);
    }

    // PHP5
    function __toString() {
        return $this->toString();
    }

    function toString() {

        $buffer = "";

        for ($i = 0; $i < $this->getLength(); $i++) {
            if ($i > 0) {
                $buffer .= ",";
            }
            $buffer .= $this->get($i);
        }

        return $buffer;
    }

    function toLogString() {

        $buffer = "";

        for ($i = 0; $i < $this->getLength(); $i++) {
            if ($i > 0) {
                $buffer .= ",";
            }
            $buffer .= QRMath::glog($this->get($i) );
        }

        return $buffer;
    }

    /**
     * @param \QRPolynomial $e
     *
     * @return \QRPolynomial
     */
    function multiply($e) {

        $num = QRMath::createNumArray($this->getLength() + $e->getLength() - 1);

        for ($i = 0; $i < $this->getLength(); $i++) {
            $vi = QRMath::glog($this->get($i) );

            for ($j = 0; $j < $e->getLength(); $j++) {
                $num[$i + $j] ^= QRMath::gexp($vi + QRMath::glog($e->get($j) ) );
            }
        }

        return new QRPolynomial($num);
    }

    /**
     * @param \QRPolynomial $e
     *
     * @return $this|\QRPolynomial
     */
    function mod($e) {

        if ($this->getLength() - $e->getLength() < 0) {
            return $this;
        }

        $ratio = QRMath::glog($this->get(0) ) - QRMath::glog($e->get(0) );

        $num = QRMath::createNumArray($this->getLength() );
        for ($i = 0; $i < $this->getLength(); $i++) {
            $num[$i] = $this->get($i);
        }

        for ($i = 0; $i < $e->getLength(); $i++) {
            $num[$i] ^= QRMath::gexp(QRMath::glog($e->get($i) ) + $ratio);
        }

        $newPolynomial = new QRPolynomial($num);
        return $newPolynomial->mod($e);
    }
}

//---------------------------------------------------------------
// Mode
//---------------------------------------------------------------

define("QR_MODE_NUMBER", 1 << 0);
define("QR_MODE_ALPHA_NUM", 1 << 1);
define("QR_MODE_8BIT_BYTE", 1 << 2);
define("QR_MODE_KANJI", 1 << 3);

//---------------------------------------------------------------
// MaskPattern
//---------------------------------------------------------------

define("QR_MASK_PATTERN000", 0);
define("QR_MASK_PATTERN001", 1);
define("QR_MASK_PATTERN010", 2);
define("QR_MASK_PATTERN011", 3);
define("QR_MASK_PATTERN100", 4);
define("QR_MASK_PATTERN101", 5);
define("QR_MASK_PATTERN110", 6);
define("QR_MASK_PATTERN111", 7);

//---------------------------------------------------------------
// ErrorCorrectLevel

// 7%.
define("QR_ERROR_CORRECT_LEVEL_L", 1);
// 15%.
define("QR_ERROR_CORRECT_LEVEL_M", 0);
// 25%.
define("QR_ERROR_CORRECT_LEVEL_Q", 3);
// 30%.
define("QR_ERROR_CORRECT_LEVEL_H", 2);


//---------------------------------------------------------------
// QRBitBuffer
//---------------------------------------------------------------

class QRBitBuffer {

    var $buffer;
    var $length;

    function __construct() {
        $this->buffer = array();
        $this->length = 0;
    }

    function getBuffer() {
        return $this->buffer;
    }

    function getLengthInBits() {
        return $this->length;
    }

    function __toString() {
        $buffer = "";
        for ($i = 0; $i < $this->getLengthInBits(); $i++) {
            $buffer .= $this->get($i)? '1' : '0';
        }
        return $buffer;
    }

    function get($index) {
        $bufIndex = (int)floor($index / 8);
        return ( ($this->buffer[$bufIndex] >> (7 - $index % 8) ) & 1) == 1;
    }

    function put($num, $length) {

        for ($i = 0; $i < $length; $i++) {
            $this->putBit( ( ($num >> ($length - $i - 1) ) & 1) == 1);
        }
    }

    function putBit($bit) {

        $bufIndex = (int)floor($this->length / 8);
        if (count($this->buffer) <= $bufIndex) {
            $this->buffer[] = 0;
        }

        if ($bit) {
            $this->buffer[$bufIndex] |= (0x80 >> ($this->length % 8) );
        }

        $this->length++;
    }
}




function carregarDadosEmailReserva(PDO $conn, string $tipo, string $codigo, array $extra = []): array {
    $map = [
        'alojamento' => ['reservas_alojamento', 'alojamentos', 'alojamento_id', 'proprietario_id', 'data_checkin', 'data_checkout'],
        'carro' => ['reservas_carro', 'carros', 'carro_id', 'usuario_id', 'data_levantamento', 'data_devolucao'],
        'experiencia' => ['reservas_experiencia', 'experiencias', 'experiencia_id', 'usuario_id', 'data_participacao', 'data_participacao'],
    ];
    if (!isset($map[$tipo])) throw new InvalidArgumentException('Invalid booking category');
    [$table, $listing, $fk, $owner, $start, $end] = $map[$tipo];
    $stmt = $conn->prepare('SELECT * FROM `' . $table . '` WHERE codigo_reserva = :codigo LIMIT 1');
    $stmt->execute(['codigo' => $codigo]);
    $r = $stmt->fetch(PDO::FETCH_ASSOC);
    if (!$r || (int) ($r['is_bloqueio'] ?? 0) === 1) throw new RuntimeException('Booking not found');
    $stmt = $conn->prepare('SELECT * FROM `' . $listing . '` WHERE id = :id LIMIT 1');
    $stmt->execute(['id' => $r[$fk]]);
    $l = $stmt->fetch(PDO::FETCH_ASSOC) ?: [];
    $stmt = $conn->prepare('SELECT id, nome, email, phone FROM usuarios WHERE id = :id LIMIT 1');
    $stmt->execute(['id' => $r['usuario_id']]);
    $u = $stmt->fetch(PDO::FETCH_ASSOC);
    if (!$u) throw new RuntimeException('Booking customer missing');
    $stmt->execute(['id' => $l[$owner] ?? 0]);
    $host = $stmt->fetch(PDO::FETCH_ASSOC) ?: [];
    $people = (int) ($r['quantidade_hospedes'] ?? $r['quantidade_pessoas'] ?? 1);
    $length = (int) ($r['noites'] ?? $r['dias'] ?? 0);
    $details = $tipo === 'experiencia' ? $people . ' participante(s)' : $length . ($tipo === 'carro' ? ' dia(s) de aluguer' : ' noite(s) · ' . $people . ' hóspede(s)');
    if ($tipo === 'carro') {
        $specs = array_filter([$l['marca'] ?? '', $l['modelo'] ?? '', $l['transmissao'] ?? '', $l['combustivel'] ?? '']);
        if ($specs) $details .= ' · ' . implode(' · ', $specs);
    } elseif ($tipo === 'experiencia') {
        if (!empty($l['duracao'])) $details .= ' · ' . $l['duracao'];
        if ((int) ($r['quantidade_jet_skis'] ?? 0) > 0) $details .= ' · ' . (int) $r['quantidade_jet_skis'] . ' jet ski(s)';
    }
    $photo = $l['imagem_url'] ?? $l['imagem_principal'] ?? $l['foto'] ?? $extra['imagem'] ?? '';
    $items = [];
    foreach (($extra['quartos'] ?? []) as $q) {
        if (!is_array($q)) continue;
        $items[] = ['nome' => (string) ($q['nome'] ?? 'Quarto'), 'imagem' => (string) ($q['imagem'] ?? ''),
            'descricao' => (int) ($q['quantidade'] ?? 1) . ' quarto(s)' . (!empty($q['capacidade']) ? ' · ' . (int) $q['capacidade'] . ' hóspede(s)' : '')];
    }
    $rows = [];
    if ($tipo === 'alojamento' && isset($r['subtotal_noites']) && abs((float) $r['subtotal_noites'] + (float) ($r['taxa_limpeza'] ?? 0) - (float) $r['preco_total']) < 0.02) {
        $rows[] = ['descricao' => $length . ' noite(s)', 'valor' => $r['subtotal_noites']];
        if ((float) ($r['taxa_limpeza'] ?? 0) > 0) $rows[] = ['descricao' => 'Taxa de limpeza', 'valor' => $r['taxa_limpeza']];
    } else $rows[] = ['descricao' => $details, 'valor' => $r['preco_total']];
    return [
        'tipo' => $tipo, 'reserva_id' => $r['id'], 'usuario_id' => $r['usuario_id'], 'codigo_reserva' => $r['codigo_reserva'],
        'status' => $r['status'], 'status_pagamento' => $r['pagamento_status'], 'preco_total' => $r['preco_total'],
        'titulo' => $l['titulo'] ?? $l['nome'] ?? $extra['experiencia'] ?? ucfirst($tipo),
        'imagem' => $photo, 'localizacao' => $l['localizacao'] ?? $l['cidade'] ?? $l['ilha'] ?? '',
        'morada' => $l['morada_completa'] ?? $l['endereco'] ?? $l['localizacao'] ?? '',
        'latitude' => $l['latitude'] ?? $l['coordenadas_lat'] ?? null,
        'longitude' => $l['longitude'] ?? $l['coordenadas_lng'] ?? null,
        'duracao' => $l['duracao'] ?? '',
        'quartos_quantidade' => array_sum(array_map(static function ($q) { return (int) ($q['quantidade'] ?? 1); }, $extra['quartos'] ?? [])),
        'pessoas_resumo' => $people . ($tipo === 'experiencia' ? ' participante(s)' : ' pessoa(s)'),
        'inicio' => $r[$start], 'fim' => $r[$end], 'hora_inicio' => $r['hora_levantamento'] ?? $l['hora_checkin'] ?? '',
        'hora_fim' => $r['hora_devolucao'] ?? $l['hora_checkout'] ?? '', 'horario' => $r['horario'] ?? '',
        'detalhes' => $details, 'itens' => $tipo === 'alojamento' ? $items : [], 'linhas_pagamento' => $rows,
        'nome_cliente' => $u['nome'], 'email_cliente' => $u['email'], 'phone_cliente' => $u['phone'],
        'anfitriao_nome' => $host['nome'] ?? '', 'anfitriao_phone' => $host['phone'] ?? '', 'anfitriao_email' => $host['email'] ?? '',
        'participante_principal' => $extra['participante_principal'] ?? [], 'participantes_adicionais' => $extra['participantes_adicionais'] ?? [],
        'metodo_pagamento' => $r['metodo_pagamento'] ?? $extra['metodo_pagamento'] ?? '',
        'referencia_pagamento' => $r['payment_intent_id'] ?? $r['stripe_id'] ?? '',
        'instrucoes' => $l['instrucoes_checkin'] ?? $l['ponto_encontro'] ?? '',
        // No generic listing policy is presented as an immutable booking policy.
        'cancelamento' => $r['condicoes_cancelamento'] ?? 'Aplicam-se as condições aceites no momento da reserva. Consulte os detalhes da sua reserva.',
    ];
}

function urlComprovativoReserva(array $d, string $secret, ?int $expires = null): string {
    if ($secret === '') throw new RuntimeException('Receipt signing key missing');
    $expires = $expires ?? time() + 7 * 86400;
    $payload = $d['tipo'] . '|' . $d['codigo_reserva'] . '|' . $expires;
    return 'https://welovepalop.com/api/comprovativo-reserva.php?' . http_build_query([
        'tipo' => $d['tipo'], 'codigo' => $d['codigo_reserva'], 'expira' => $expires,
        'assinatura' => hash_hmac('sha256', $payload, $secret),
    ], '', '&', PHP_QUERY_RFC3986);
}


/** A4 vector drawing. Coordinates are points measured from the top left. */
class ComprovativoReservaPDF {
    public $stream = '';
    public $links = [];
    public $images = [];
    public function color(string $hex, bool $fill = true): void {
        $rgb = sscanf(ltrim($hex, '#'), '%02x%02x%02x');
        $this->stream .= sprintf('%.3f %.3f %.3f %s ', $rgb[0]/255, $rgb[1]/255, $rgb[2]/255, $fill ? 'rg' : 'RG');
    }
    public function line(float $x,float $y,float $x2,float $y2,string $color='#bfc3c8',float $width=.6,bool $dash=false): void {
        $this->color($color,false);
        $this->stream .= sprintf('%.2f w %s %.2f %.2f m %.2f %.2f l S [] 0 d ', $width,$dash?'[2 2] 0 d':'[] 0 d',$x,842-$y,$x2,842-$y2);
    }
    public function box(float $x,float $y,float $w,float $h,string $stroke='#ffffff',?string $fill=null,float $radius=0): void {
        $this->color($stroke,false); if($fill!==null) $this->color($fill);
        $this->stream .= '.9 w '; $b=842-$y-$h;
        if(!$radius) $this->stream .= sprintf('%.2f %.2f %.2f %.2f re ',$x,$b,$w,$h);
        else {
            $r=min($radius,$w/2,$h/2);$k=.55228475*$r;
            $this->stream .= sprintf('%.2f %.2f m %.2f %.2f l %.2f %.2f %.2f %.2f %.2f %.2f c %.2f %.2f l %.2f %.2f %.2f %.2f %.2f %.2f c %.2f %.2f l %.2f %.2f %.2f %.2f %.2f %.2f c %.2f %.2f l %.2f %.2f %.2f %.2f %.2f %.2f c h ',
                $x+$r,$b,$x+$w-$r,$b,$x+$w-$r+$k,$b,$x+$w,$b+$r-$k,$x+$w,$b+$r,
                $x+$w,$b+$h-$r,$x+$w,$b+$h-$r+$k,$x+$w-$r+$k,$b+$h,$x+$w-$r,$b+$h,
                $x+$r,$b+$h,$x+$r-$k,$b+$h,$x,$b+$h-$r+$k,$x,$b+$h-$r,
                $x,$b+$r,$x,$b+$r-$k,$x+$r-$k,$b,$x+$r,$b);
        }
        $this->stream .= $fill===null?'S ':'B ';
    }
    public function text(float $x,float $y,string $text,float $size=10,bool $bold=false,string $color='#13151b'): void {
        $this->color($color);
        $latin=iconv('UTF-8','Windows-1252//TRANSLIT',$text);
        $latin=preg_replace('/[\x00-\x1f\x7f]/',' ',$latin===false?'':$latin);
        $latin=str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$latin);
        $this->stream .= sprintf('BT /%s %.2f Tf 1 0 0 1 %.2f %.2f Tm (%s) Tj ET ',$bold?'F2':'F1',$size,$x,842-$y,$latin);
    }
    public function width(string $s,float $size): float {
        $latin=iconv('UTF-8','Windows-1252//TRANSLIT',$s);$w=0;
        foreach(str_split($latin===false?'':$latin) as $c) $w+=strpos(' ilI.,:;!|',$c)!==false?.26:(strpos('MW@%',$c)!==false?.86:.53);
        return $w*$size;
    }
    public function wrap(string $s,float $width,float $size): array {
        $lines=[];$line='';
        foreach(preg_split('/\s+/u',trim($s))?:[] as $word) {
            if($line!=='' && $this->width($line.' '.$word,$size)>$width) {$lines[]=$line;$line='';}
            $line.=($line===''?'':' ').$word;
        }
        if($line!=='') $lines[]=$line;
        return $lines;
    }
    public function paragraph(float $x,float $y,string $s,float $w,float $size=10,float $leading=14,bool $bold=false,string $color='#36383d'): float {
        foreach($this->wrap($s,$w,$size) as $line) {$this->text($x,$y,$line,$size,$bold,$color);$y+=$leading;}
        return $y;
    }
    public function link(float $x,float $y,float $w,float $h,string $url): void {$this->links[]=[$x,842-$y-$h,$x+$w,842-$y,$url];}
    public function bed(float $x,float $y,string $color='#0755b1'): void {
        $this->box($x,$y+6,17,8,$color,null,1);$this->box($x+1,$y,15,7,$color,null,1);
        $this->line($x,$y+13,$x,$y+18,$color,1.5);$this->line($x+17,$y+13,$x+17,$y+18,$color,1.5);
    }
    public function icon(int $kind,float $x,float $y): void {
        $c='#666a70';
        if($kind===0 || $kind===4) {
            $this->box($x,$y,13,10,$c,null,1);$this->line($x,$y+3,$x+13,$y+3,$c,1.3);
            $this->line($x+2,$y+7,$x+5,$y+7,$c,.8);
        } elseif($kind===1) {
            $this->box($x+2,$y-1,9,13,$c,null,1);
            foreach([3,6,9] as $dy) $this->line($x+4,$y+$dy,$x+9,$y+$dy,$c,.7);
        } elseif($kind===2) $this->text($x,$y+11,'#',18,false,$c);
        elseif($kind===3) {
            $this->box($x,$y+5,9,6,$c,null,3);$this->box($x+6,$y-1,9,6,$c,null,3);
            $this->line($x+5,$y+7,$x+10,$y+2,$c,1);
        } else {$this->box($x-1,$y-2,15,15,$c,null,7.5);$this->text($x+3,$y+9,'?',12,false,$c);}
    }
    public function itemIcon(string $tipo,float $x,float $y,string $color='#0755b1'): void {
        if($tipo==='alojamento') {$this->bed($x,$y,$color);return;}
        if($tipo==='carro') {
            $this->box($x,$y+5,18,9,$color,null,2);$this->box($x+3,$y,12,7,$color,null,2);
            $this->box($x+2,$y+12,4,4,$color,'#ffffff',2);$this->box($x+12,$y+12,4,4,$color,'#ffffff',2);
        } else {
            $this->box($x,$y,18,18,$color,null,9);$this->line($x+5,$y+13,$x+12,$y+5,$color,1.4);
            $this->line($x+12,$y+5,$x+12,$y+10,$color,1);$this->line($x+5,$y+13,$x+5,$y+8,$color,1);
        }
    }
    public function qr(string $code,float $x,float $y,float $size): void {
        $qr=QRCode::getMinimumQRCode($code,QR_ERROR_CORRECT_LEVEL_M);
        $count=$qr->getModuleCount();$cell=$size/($count+8);
        $this->box($x,$y,$size,$size,'#ffffff','#ffffff');$this->color('#000000');
        for($row=0;$row<$count;$row++) for($col=0;$col<$count;$col++) if($qr->isDark($row,$col))
            $this->stream.=sprintf('%.3f %.3f %.3f %.3f re f ',$x+($col+4)*$cell,842-$y-($row+5)*$cell,$cell+.015,$cell+.015);
    }
    public function jpeg(string $bytes,float $x,float $y,float $w,float $h): bool {
        if(substr($bytes,0,8)==="\x89PNG\r\n\x1a\n") {
            $i=8;$data='';$palette='';$info=null;
            while($i+12<=strlen($bytes)) {
                $n=unpack('N',substr($bytes,$i,4))[1];$type=substr($bytes,$i+4,4);$chunk=substr($bytes,$i+8,$n);
                if(strlen($chunk)!==$n) return false;
                if($type==='IHDR') $info=unpack('Nwidth/Nheight/Cbits/Ctype/Ccompression/Cfilter/Cinterlace',$chunk);
                elseif($type==='PLTE') $palette=$chunk;
                elseif($type==='IDAT') $data.=$chunk;
                elseif($type==='IEND') break;
                $i+=$n+12;
            }
            if(!$info || $info['interlace']!==0 || !in_array($info['type'],[0,2,3],true) || $data==='') return false;
            if($info['type']===3 && $palette==='') return false;
            $info['channels']=$info['type']===2?3:1;
            $info['space']=$info['type']===3?'[/Indexed /DeviceRGB '.((int)(strlen($palette)/3)-1).' <'.bin2hex($palette).'>]':($info['type']===2?'/DeviceRGB':'/DeviceGray');
            $info['png']=true;
            $name='Im'.(count($this->images)+1);$this->images[$name]=[$data,$info];
            $this->stream.=sprintf('q %.2f 0 0 %.2f %.2f %.2f cm /%s Do Q ',$w,$h,$x,842-$y-$h,$name);return true;
        }
        if(substr($bytes,0,2)!=="\xff\xd8") return false;
        $i=2;$length=strlen($bytes);$info=null;
        while($i+9<$length) {
            if(ord($bytes[$i])!==255) {$i++;continue;}
            $marker=ord($bytes[$i+1]);$i+=2;
            if($marker===217 || $marker===218) break;
            if($marker===216 || $marker===1 || ($marker>=208 && $marker<=215)) continue;
            $n=unpack('n',substr($bytes,$i,2))[1];if($n<2) break;
            if(in_array($marker,[192,193,194],true)) {$info=unpack('Cbits/nheight/nwidth/Cchannels',substr($bytes,$i+2,6));break;}
            $i+=$n;
        }
        if(!$info || !in_array($info['channels'],[1,3],true)) return false;
        $name='Im'.(count($this->images)+1);$this->images[$name]=[$bytes,$info];
        $this->stream.=sprintf('q %.2f 0 0 %.2f %.2f %.2f cm /%s Do Q ',$w,$h,$x,842-$y-$h,$name);return true;
    }
    public function output(): string {
        $objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','',
            '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>',
            '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>',
            '<< /Length '.strlen($this->stream).">>\nstream\n".$this->stream."\nendstream"];
        $resources='';$annotations=[];
        foreach($this->images as $name=>[$bytes,$info]) {
            $id=count($objects)+1;$resources.='/'.$name.' '.$id.' 0 R ';
            $png=!empty($info['png']);
            $space=$png?$info['space']:'/'.($info['channels']===1?'DeviceGray':'DeviceRGB');
            $filter=$png?'/FlateDecode /DecodeParms << /Predictor 15 /Colors '.$info['channels'].' /BitsPerComponent '.$info['bits'].' /Columns '.$info['width'].' >>':'/DCTDecode';
            $objects[]='<< /Type /XObject /Subtype /Image /Width '.$info['width'].' /Height '.$info['height'].' /ColorSpace '.$space.' /BitsPerComponent '.($png?$info['bits']:8).' /Filter '.$filter.' /Length '.strlen($bytes).">>\nstream\n".$bytes."\nendstream";
        }
        foreach($this->links as [$x,$y,$x2,$y2,$url]) {
            $id=count($objects)+1;$annotations[]=$id.' 0 R';
            $url=str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$url);
            $objects[]=sprintf('<< /Type /Annot /Subtype /Link /Rect [%.2f %.2f %.2f %.2f] /Border [0 0 0] /A << /S /URI /URI (%s) >> >>',$x,$y,$x2,$y2,$url);
        }
        $objects[2]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R /F2 5 0 R >> /XObject << '.$resources.' >> >> /Contents 6 0 R /Annots ['.implode(' ',$annotations).'] >>';
        $pdf="%PDF-1.4\n";$offsets=[0];
        foreach($objects as $i=>$object) {$offsets[]=strlen($pdf);$pdf.=($i+1)." 0 obj\n".$object."\nendobj\n";}
        $xref=strlen($pdf);$count=count($objects)+1;$pdf.="xref\n0 ".$count."\n0000000000 65535 f \n";
        foreach(array_slice($offsets,1) as $offset) $pdf.=sprintf("%010d 00000 n \n",$offset);
        return $pdf."trailer\n<< /Size ".$count." /Root 1 0 R >>\nstartxref\n".$xref."\n%%EOF";
    }
}

/** Fetch only a fixed map provider, never an arbitrary request URL. */
function mapaComprovativoReserva(array $d,array $settings): string {
    $lat=filter_var($d['latitude']??null,FILTER_VALIDATE_FLOAT);$lng=filter_var($d['longitude']??null,FILTER_VALIDATE_FLOAT);
    $token=$settings['mapbox_token']??getenv('MAPBOX_TOKEN');
    if($lat===false || $lng===false || abs($lat)>85 || abs($lng)>180 || !$token || !function_exists('curl_init')) return '';
    $point=sprintf('%.6F,%.6F',$lng,$lat);
    $url='https://api.mapbox.com/styles/v1/mapbox/streets-v12/static/pin-l+0755b1('.$point.')/'.$point.',14/640x470.png?access_token='.rawurlencode($token);
    $curl=curl_init($url);curl_setopt_array($curl,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>6,CURLOPT_CONNECTTIMEOUT=>3,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_SSL_VERIFYPEER=>true]);
    $bytes=curl_exec($curl);$status=curl_getinfo($curl,CURLINFO_HTTP_CODE);curl_close($curl);
    return $status===200 && is_string($bytes) && strlen($bytes)<2500000?$bytes:'';
}

